        protected bool IsFIBettype(int bettype)
        {
            switch (bettype)
            {
                case 51:
                case 52:
                case 53:
                case 54:
                case 55:
                case 56:
                case 61:
                case 62:
                case 63:
                case 64:
                case 65:
                case 66:
